    if pos == n:
        return 1 if total == target else 0
    count = 0
    value = 0
    for end in range(pos, n):
        if end > pos and d[pos] == "0":
            break                                # no number with a leading zero
        value = value * 10 + int(d[end])
        if pos == 0:
            count += search(end + 1, value, value)
        else:
            count += search(end + 1, total + value, value)                      # +
            count += search(end + 1, total - value, -value)                     # -
            count += search(end + 1, total - last + last * value, last * value)  # *
    return count

